={{ JSON.stringify({
  model: 'openai/gpt-oss-120b',
  response_format: { type: 'json_object' },
  reasoning_effort: 'low',
  messages: [
    { role: 'system', content: [
      'Tarefa: converter a mensagem de WhatsApp de um engenheiro de obra, pedindo material de construcao, numa lista de itens para cotar com fornecedores.',
      'Como montar a lista:',
      '- um item para cada material citado, com a quantidade e a unidade (ou embalagem) quando a mensagem trouxer;',
      '- mantenha as palavras do engenheiro: nome do produto, marca, giria e embalagem (balde, lata, saco, rolo, galao, caixa, pacote, metro, kg e assim por diante). Ajuste somente o plural pelo numero (1 balde, 30 sacos);',
      '- nao use sinonimo, nao encaixe a unidade numa lista fechada e nao corrija nome de produto ou marca, por mais estranho que pareca; so arrume erro evidente de gramatica no resto do texto;',
      '- informacao que nao esta na mensagem vira null, sem suposicao;',
      '- se a mensagem citar obra, empreendimento ou endereco, copie para o campo obra; senao obra e null.',
      'Saida: apenas JSON valido, sem texto antes nem depois, no formato {"obra": string ou null, "itens": [{"descricao": string, "unidade": string ou null, "quantidade": number ou null}]}.',
      'Exemplo 1. Mensagem: "preciso de 20 latas de tinta e 4 rolos de manta" => {"obra": null, "itens": [{"descricao": "tinta", "unidade": "latas", "quantidade": 20}, {"descricao": "manta", "unidade": "rolos", "quantidade": 4}]}',
      'Exemplo 2. Mensagem: "manda 1 caixa de azulejo 60x60 pra Residencial Aurora" => {"obra": "Residencial Aurora", "itens": [{"descricao": "azulejo 60x60", "unidade": "caixa", "quantidade": 1}]}'
    ].join('\n') },
    { role: 'user', content: $json.texto }
  ]
}) }}

parameters.jsCode:
// A Groq responde no formato da OpenAI: o JSON util vem como texto em choices[0].message.content.
const conteudo = $json.choices?.[0]?.message?.content;
if (!conteudo) {
  throw new Error('Groq respondeu sem choices: ' + JSON.stringify($json));
}

const { obra = null, itens } = JSON.parse(conteudo);

if (!Array.isArray(itens) || itens.length < 1) {
  throw new Error('A mensagem do engenheiro nao trouxe nenhum item reconhecivel.');
}

return [{ json: { obra, itens } }];

const pedido = $('Registrar Cotacao').first().json;
const extracao = $('Ler JSON da Extracao').first().json;

const linhas = extracao.itens.map((item, i) => {
  const qtd = item.quantidade == null
    ? '(quantidade a confirmar)'
    : `${item.quantidade}${item.unidade ? ' ' + item.unidade : ''}`;
  return `${i + 1}. ${item.descricao} - ${qtd}`;
});

const cabecalho = [`*Solicitacao de cotacao ${pedido.codigo}*`];
if (extracao.obra) cabecalho.push(`Obra: ${extracao.obra}`);

const texto = [
  ...cabecalho,
  '',
  ...linhas,
  '',
  'Responda nesta conversa com o preco unitario, o prazo de entrega e a condicao de pagamento. Prazo para responder: 24 horas.'
].join('\n');

return $input.all().map(({ json: f }) => ({
  json: { id_fornecedor: f.id, nome_fornecedor: f.nome, conversa_id: f.conversa_id, texto }
}));
